PAGES = {
'about': dict(title='About MyAudioShelf', eyebrow='Story first. Always.', heading='Every great story deserves a great sound.', intro='MyAudioShelf is a proposed UK audio storytelling and technology business creating immersive audiobooks, dramatised productions, children’s stories and new ways to experience narrative.', cards=[('Our purpose','Bring written worlds to life through professional performance, thoughtful sound design and music.'),('Our vision','Build a creative audio ecosystem spanning audiobooks, audio drama, education, original worlds and future interactive experiences.'),('Story first','The work and its author guide every creative decision.'),('Quality and imagination','Careful casting, direction, editing and mastering serve the listening experience.'),('Accessibility','Clear controls, readable content and inclusive production help more people enjoy stories.'),('Responsible technology','Technology supports human creativity. Authors and producers retain control over their work and production choices.')]),
'services': dict(title='Our services', eyebrow='From manuscript to headphones', heading='We turn stories into experiences.', intro='Choose a production approach shaped around your story, audience and creative ambition. Scope, availability and delivery are agreed with you before production begins.', cards=[('Audiobook production','Professional narration, recording, editing, mastering and delivery.'),('Dramatised audiobooks','Character performances, multi-actor casting and carefully directed scenes.'),('Sound design','Environmental ambience, Foley and effects that support the narrative.'),('Original music','Sonic themes and musical direction developed around the story.'),('Children’s audio','Imaginative storytelling and educational audio for young listeners.'),('Audio adaptation','Developing written material into compelling audio scripts and productions.'),('Multilingual audio','Planning voices, language adaptation and listening experiences for different audiences.'),('Audio branding','Voice and audio production for organisations and creative projects.')]),
'children': dict(title='MyAudioShelf Kids', eyebrow='Little ears. Unlimited imagination.', heading='Big stories for little ears.', intro='MyAudioShelf Kids is our developing children’s audio programme: imaginative, entertaining and educational experiences that help young listeners discover the joy of stories.', cards=[('Bedtime stories','Gentle worlds and reassuring voices for quieter listening moments.'),('Adventure stories','Characters, journeys and discoveries that encourage imagination.'),('Learning through story','Future productions exploring vocabulary, educational questions and character development.'),('Bilingual stories','A developing direction for language learning and culturally rich storytelling.'),('For parents','Age guidance and clear descriptions help you choose suitable listening. Children’s profiles and parental controls are future features.'),('For schools','Talk to us about educational storytelling, classroom listening and commissioned audio projects.')]),
'originals': dict(title='MyAudioShelf Originals', eyebrow='Original worlds. Lasting possibilities.', heading='Stories created by us. Worlds built to grow.', intro='Our vision for MyAudioShelf Originals brings together original audiobooks, children’s characters, audio series and educational stories. Published productions will have their own credits, characters and listening pages.', cards=[('Original audio worlds','Stories developed for the listening experience from the beginning.'),('Characters with a future','A long-term direction for children’s series and recurring story worlds.'),('Create with us','We welcome conversations with writers, actors, narrators, composers and sound designers.')]),
'immersive-audio': dict(title='Immersive audio', eyebrow='Voice + performance + sound + music + atmosphere', heading='Enter the story.', intro='A voice can tell you where you are. An immersive production lets you hear the world around it. Sound and performance work together, always in service of the story.', cards=[('Classic','Professional narration with the voice and the text at the centre.'),('Enhanced','Narration supported by carefully chosen music, ambience and effects.'),('Dramatised','Multiple actors, character performances and cinematic sound design.'),('Interactive · future direction','We are exploring experiences in which listeners may participate in how a story unfolds.'),('Behind the production','Casting and creative direction establish the performances. Editing, sound design and mastering shape the finished experience.'),('Sound with purpose','Environment, pacing and emotional tone guide the treatment. Effects should clarify a scene rather than distract from it.')]),
'innovation': dict(title='Innovation', eyebrow='Research and development', heading='The future of storytelling is immersive.', intro='We are developing narrative-aware production intelligence for long-form audiobook creation. Our proposed technology aims to maintain story and production memory across an entire literary work, with the author or producer in control.', cards=[('StoryDNA Engine','Proposed manuscript analysis for characters, locations, dialogue, scene boundaries, actions, emotional states and recurring elements.'),('Story Intelligence Profile','A persistent project model for characters, environments, relationships, motifs and author-approved production decisions.'),('Narrative Sound Engine','Proposed recommendations for ambience and production treatment using scene context, emotion and prior creative decisions.'),('Audio Continuity Engine','Designed to recall earlier narrative context and flag potential inconsistencies when characters, locations or motifs recur.'),('Author Control Layer','Accept, modify or reject proposed treatments. Approved decisions are intended to become part of the project’s production memory.'),('Beyond the first version','Our innovation programme explores adaptive audio, multilingual storytelling, accessible listening, children’s learning and interactive experiences. These capabilities are under development, not available as finished products.')]),
'accessibility': dict(title='Accessibility', eyebrow='Stories for more people', heading='A more accessible listening experience.', intro='We design MyAudioShelf around readable content, keyboard navigation and clear audio controls. Accessibility is an ongoing part of the platform’s development.', cards=[('Navigate your way','Use the skip link, keyboard focus and labelled form controls throughout the platform.'),('Listen at your pace','Audio controls support play, pause and seeking. Purchased chapter playback also supports playback speed.'),('Motion and sound','Reduced-motion preferences are respected. Book-opening sounds can be muted from the navigation.'),('Tell us what needs work','Contact us with an accessibility issue, the affected page and your browser or assistive technology so we can investigate.')]),
'privacy': dict(title='Privacy', eyebrow='Your information', heading='Your story. Your privacy.', intro='This page describes how the current platform handles information. Please contact us if you have questions about your data.', cards=[('Enquiries and manuscripts','We store the contact details, project information and optional files you submit so authorised staff can review your enquiry. Manuscripts are stored privately and are not used for automated StoryDNA analysis in this version.'),('Purchases and listening','The platform stores order details, email-linked access rights and listening progress. Payment collection is handled by Stripe when real payments are enabled.'),('Email updates','Newsletter registration requires your agreement. Delivery campaigns are not yet enabled; contact us to request removal from the stored list.'),('Preferences and sessions','Essential session cookies support security, cart and access. Browser storage remembers theme and book-sound preferences.'),('Usage information','We record aggregate page, preview and enquiry events to understand platform use. The platform does not currently use an external advertising analytics service or determine visitor countries.'),('Your choices','Contact us to request access, correction or deletion of your submitted information. Staff review requests alongside any order records that need to be retained.')]),
 'terms': dict(title='Platform terms', eyebrow='Using MyAudioShelf', heading='Clear expectations for every story.', intro='Use the platform responsibly and submit only material you are authorised to share. Production scope and rights are agreed separately before any project begins.', cards=[('Production enquiries','Submitting an enquiry does not create a production contract. Pricing, deliverables, permissions and timelines require a separate agreement.'),('Sample content','Fictional sample titles and demonstration audio illustrate the platform. They are not licensed commercial audiobooks and cannot be purchased through real Stripe payments.'),('Creative rights','Authors and rights holders retain their rights. Do not upload manuscripts, recordings or other material without permission.'),('Technology in development','Innovation descriptions explain our proposed direction. They do not promise that research capabilities are currently available.'),('Purchased audio','Streaming and new downloads of purchased audio depend on a verified paid purchase and its current entitlement. Copies already downloaded cannot be recalled when access is revoked. Contact the team for order or access issues.')]),
}
PROCESS=[('Submit your project','Tell us about the book, audience and production you have in mind.'),('Creative assessment','Discuss the story and the production format that best serves it.'),('Production planning','Agree adaptation, casting, sound direction and scope.'),('Recording','Capture and direct the voices that bring the story to life.'),('Post-production','Edit performances, develop sound and music, and master the audio.'),('Delivery','Prepare the agreed final audio and supporting materials for distribution.')]
